const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Sakha Republic approximate bounds
  const sakha = ee.Geometry.Polygon([
    [[105, 50], [165, 50], [165, 80], [105, 80], [105, 50]]
  ]);

  const date = '2020-08-06';

  // 2. Data Acquisition - MODIS Active Fires
  const fires = ee.ImageCollection('MODIS/006/MCD14DL')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filterBounds(sakha);

  const fireCount = fires.size().getInfo();
  console.log(`Fire detections on ${date}: ${fireCount}`);

  // Check for empty collection
  if (fireCount === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Count fire pixels
  const fireImg = fires.select('MaxFRP').mosaic();
  const fireStats = fireImg.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: sakha,
    scale: 1000,
    maxPixels: 1e9
  });

  const pixelCount = fireStats.get('MaxFRP').getInfo();
  console.log(`Active fire pixels: ${pixelCount}`);

  // Check for no valid pixels
  if (pixelCount === 0) {
    console.log("<answer>B</answer>");
    return;
  }

  // 4. Validation & Final Answer
  if (pixelCount === null || pixelCount === undefined || pixelCount < 0) {
    console.log("<answer>C3</answer>");
  } else if (pixelCount > 8) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
